"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["66629"],{55486(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.texto_nao_gravavel","status":422,"titulo":"Texto do modelo com caractere nulo ou Unicode inv\xe1lido"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.texto_nao_gravavel","requisitos":[],"oQueAconteceu":["A cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou a atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`) de um modelo de formul\xe1rio trouxe um texto com o caractere nulo (`U+0000`) ou que n\xe3o \xe9 Unicode v\xe1lido. O banco de dados n\xe3o grava o caractere nulo, e o conte\xfado do modelo \xe9 gravado como documento; a recusa vem das regras do modelo, antes de o texto chegar ao banco. A confer\xeancia cobre o `codigo`, o `nome`, a `descricao`, o `tipoProcessoCodigo` e os textos do `conteudo`: t\xedtulos, c\xf3digos, r\xf3tulos, ajudas, mensagens, os fatos e os valores citados nas condi\xe7\xf5es, os pressupostos e os dados dos documentos exigidos.","A recusa vem na lista `errors` da resposta, com `field` apontando o texto, por exemplo `nome` ou `conteudo.itens[0].rotulo`, uma entrada por campo. Os textos do conte\xfado s\xf3 s\xe3o conferidos depois que ele \xe9 lido sem recusa de leitura. Um `tipoProcessoCodigo` assim n\xe3o \xe9 procurado no cadastro de tipos de processo, e por isso a resposta n\xe3o traz, junto, [tipo de processo inexistente](/erros/uniplus.configuracao.modelo_formulario.tipo_processo_inexistente). Nada \xe9 gravado. Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado). S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Remova o caractere inv\xe1lido do texto indicado em `field` e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);